-- demo dean names and messages for all branches
UPDATE institute_branches SET dean_name_ar = 'أ.د/ محمد أحمد الشامي',
  dean_message_ar = E'بسم الله الرحمن الرحيم\n\nالحمد لله الذي علّم بالقلم، والصلاة والسلام على سيدنا محمد وعلى آله وصحبه أجمعين.\n\nأرحب بكم أجمل ترحيب في صفحة فرع الديوان العام للمعهد الوطني للعلوم الإدارية، منطلق هذا الصرح التعليمي الذي يهتم بإعداد الكفاءات الإدارية المؤهلة لخدمة الوطن.\n\nإن عماد النجاح هو الشراكة بين الكادر الأكاديمي والطلاب، والتعاون المتواصل في سبيل تطوير مستوى التعليم والتدريب. نسعى جاهدين لتوفير بيئة تعليمية محفّزة، وبرامج تدريبية حديثة تلبي احتياجات سوق العمل.\n\nأتطلع إلى لقائكم، متمنياً لطلابنا الأعزاء التوفيق والنجاح، وأشجع الجميع على الاستفادة القصوى من كل ما يوفره المعهد من إمكانيات أكاديمية وتدريبية.\n\nوفق الله الجميع لما فيه خير الوطن.\n\nمع خالص التقدير والتحية،'
  WHERE slug = 'sanaa';

UPDATE institute_branches SET dean_name_ar = 'أ.د/ أحمد عبدالله العريقي',
  dean_message_ar = E'بسم الله الرحمن الرحيم\n\nالأخوة الكرام، طلابنا الأعزاء في فرع عدن.\n\nيسرني أن أرحب بكم في فرع المعهد الوطني للعلوم الإدارية بعدن، محطة العمل والإباء، وأؤكد لكم أن أبواب الفرع مفتوحة أمام كل مسعى لطلب العلم والمعرفة.\n\nنحرص في الفرع على تقديم برامج نوعية في الإدارة والمحاسبة بصورة تلبي تطلعات أبناء عدن والمحافظات المجاورة، بكوادر مؤهلة ومناهج حديثة، وبيئة مشجعة على الإبداع والتميز.\n\nأدعوكم إلى الاجتهاد والمثابرة، فالمعهد أمامكم ليس بجدارٍ عالٍ، بل بسطوح مفتوحة للعلم والعمل.\n\nدمتم ذخراً للوطن،\n\nعميد فرع عدن'
  WHERE slug = 'aden';

UPDATE institute_branches SET dean_name_ar = 'د/ فؤاد محسن الشرعبي',
  dean_message_ar = E'بسم الله الرحمن الرحيم\n\nبزغ الهدف السامي من إنشاء فرع إب التعليمي هو خدمة أبناء محافظة إب والمناطق المجاورة، بتوفير التعليمة الإدارية النوعية القريبة من بيوتهم.\n\nمن هذا المنطلق يشرفني الترحيب بكم، وأعدكم ببذل كل الجهود لتطوير الخدمة التعليمية في الفرع، والسعي الدائم للارتقاء بمستوى مخرجاتنا لتتسق مع متطلبات سوق العمل الحديث.\n\nأهل إب أهل علم وجد ومثابرة، وأنا على يقين بأنهم سيكونون خير ممثلين للمعهد في مختلف الميادين.\n\nوفق الله الجميع،\n\nعميد فرع إب'
  WHERE slug = 'taiz';

UPDATE institute_branches SET dean_name_ar = 'د/ سامية يحيى باصرة',
  dean_message_ar = E'بسم الله الرحمن الرحيم\n\nالحمد لله والصلاة والسلام على رسول الله.\n\nتشرفت محافظة حضرموت بأن تحتضن هذا الفرع من المعهد الوطني للعلوم الإدارية، الذي جسد إيماننا الراسخ بأن المضي قدماً نحو المستقبل يبدأ من التعليم وتنمية القدرات.\n\nأرحب بكم في فرع حضرموت، وأدعوكم إلى الانخراط الفاعل في برامجنا التدريبية، والتعاون معنا في تطوير الفرع وخدمة مجتمعنا.\n\nنسعى دوماً إلى أن نكون عند حسن ظن أبناء المحافظة، وأن نقدم نماذج مشرفة من الخريجين القادرين على المنافسة والتميز.\n\nمع خالص الشكر والتقدير،\n\nعميدة فرع حضرموت'
  WHERE slug = 'hodeidah';

UPDATE institute_branches SET dean_name_ar = 'د/ عبدالرحمن علي الأهدل',
  dean_message_ar = E'بسم الله الرحمن الرحيم\n\nبقلوب عامرة بالمحبة والتقدير أتقدم إليكم بأصدق الترحيب في فرع المعهد الوطني للعلوم الإدارية بمحافظة الحديدة.\n\nإن فرع الحديدة يفتح أبوابه لكل طالب علم وطالبة معرفة، مهتمين بإعداد جيل متمكن من المهارات الإدارية والمحاسبية، بما يمكنه من خدمة مجتمعه والمساهمة في نهضته.\n\nأدعوكم إلى الاستفادة من ما يقدمه الفرع من برامج وأنشطة، وأشجعكم على الاجتهاد؛ فالعلم نور، والاجتهاد سبيل التفوق.\n\nوفقكم الله،\n\nعميد فرع الحديدة'
  WHERE slug = 'ibb';

UPDATE institute_branches SET dean_name_ar = 'أ.د/ خالد سعيد بافضل',
  dean_message_ar = E'بسم الله الرحمن الرحيم\n\nسلام الله عليكم ورحمته وبركاته.\n\nيسعدني أن أرحب بكم في فرع المعهد الوطني للعلوم الإدارية بمحافظة صعدة، هذا الفرع الذي يمثل امتداداً لرسالة المعهد الوطنية في التعليم الإداري. \n\nنؤمن في فرع صعدة بأن العلم قوة، وأن الاستثمار في الإنسان هو أنجح السبل لتحقيق التنمية المستدامة. لذلك نضع نصب أعيننا تقديم برامج تدريبية متميزة ترتقي بمهارات أبناء المحافظة.\n\nبفضلكم ودعمكم نستطيع أن نبني فرعاً يليق بطموحاتنا جميعاً.\n\nلكم منا أطيب التحايا،\n\nعميد فرع صعدة'
  WHERE slug = 'mukalla';